			return True
		if self.value == other.value and self.index < other.index:
			return True
		return False

	def __str__(self):
		return f'[{self.value}, {self.index}]'

class Heap:

	def __init__(self):
		self.a = [Element(0, 0)]

	def insert(self, x):
		a = self.a
		a.append(x)
		i = len(self.a) - 1
		while i > 1:
			parent_i = self._parent_index(i)
			if a[i] > a[parent_i]:
				(a[i], a[parent_i]) = (a[parent_i], a[i])
			i = parent_i

	def get_max(self):
		return self.a[1]

	def pop_max(self):
		a = self.a
		x = a[1]
		last = a.pop()
		if len(a) > 1:
			a[1] = last
			i = 1
			while i < len(a):
				left_child_i = self._left_child_index(i)
				if left_child_i >= len(a):
					left_child_i = 0
				right_child_i = self._right_child_index(i)
				if right_child_i >= len(a):
					right_child_i = 0
				max_child_i = left_child_i if a[left_child_i] > a[right_child_i] else right_child_i
				if a[max_child_i] > a[i]:
					(a[max_child_i], a[i]) = (a[i], a[max_child_i])
					i = max_child_i
				else:
					break
		return x

	@staticmethod
	def _parent_index(i):
		return i // 2

	@staticmethod
	def _left_child_index(i):
		return 2 * i

	@staticmethod
	def _right_child_index(i):
		return 2 * i + 1

	def print(self):
