	S = [c for c in S]
	S.sort(reverse=True)
	ans = [list() for _ in range(K)]
	for a in ans:
		a.append(S.pop())
	if ans[0][0] != ans[-1][0]:
		return ''.join(ans[-1])
	elif not S:
		return ''.join(ans[-1])
	elif S[0] != S[-1]:
		return ''.join(ans[-1] + list(reversed(S)))
	else:
		n = -(-len(S) // K)
		return ''.join(ans[-1] + [S[0] * n])

