def ref(N, K, S):
	S = [c for c in S]
	n = Counter(S)['?']
	iq = [i for i in range(N) if S[i] == '?']
	for j in product('01', repeat=n):
		for (k, v) in zip(iq, j):
			S[k] = v
		ok = True
		cc = Counter(S[:K])
		if cc['0'] > K // 2 or cc['1'] > K // 2:
			ok = False
		for i in range(N - K):
			a = S[i]
			b = S[i + K]
			if a != b:
				ok = False
		if ok:
			return 'YES'
	return 'NO'

def slv(N, K, S):
	sk = defaultdict(Counter)
	for i in range(N):
		sk[i % K][S[i]] += 1
	c = Counter()
	for i in range(K):
		if '0' in sk[i] and '1' in sk[i]:
			return 'NO'
		if '0' in sk[i]:
			c['0'] += 1
		elif '1' in sk[i]:
			c['1'] += 1
	if c['0'] > K // 2 or c['1'] > K // 2:
		return 'NO'
	return 'YES'

