def _read_line():
	result = _sys.stdin.readline()
	assert result[-1] == '\n'
	return result[:-1]

def _read_ints():
	return map(int, _read_line().split(' '))

def can_make_k_balanced(s, k):
	assert isinstance(s, str)
	assert k % 2 == 0
	half_k = k // 2
	slices = []
	i_slice_start = 0
	while i_slice_start < len(s):
		slices.append(s[i_slice_start:i_slice_start + k])
		i_slice_start += k
	final_slice_data = list(s[0:k])
	for slice_data in slices:
		for i in range(len(slice_data)):
			if slice_data[i] == GAP:
				continue
			if final_slice_data[i] == GAP:
				final_slice_data[i] = slice_data[i]
			elif final_slice_data[i] != slice_data[i]:
				return False
	known_sum = sum((_char_to_int(char) for char in final_slice_data if char != GAP))
	gaps_sum = half_k - known_sum
	gaps_n = final_slice_data.count(GAP)
	return 0 <= gaps_sum <= gaps_n

def _char_to_int(char):
	assert char in (ZERO, ONE)
	return int(char)
