def kBalanced(s):
	freq = [0] * 3
	for c in s:
		if c == '0':
			freq[0] += 1
		elif c == '1':
			freq[1] += 1
		else:
			freq[2] += 1
	if freq[0] == freq[1]:
		if freq[2] % 2 == 0:
			return True
		else:
			return False
	elif freq[2] < abs(freq[0] - freq[1]):
		return False
	elif (abs(freq[0] - freq[1]) - freq[2]) % 2 == 0:
		return True
	else:
		return False

def solve(n, k, s):
	k_bal = True
	startIndex = 0
	endIndex = k
	while endIndex < n:
		if s[startIndex] == s[endIndex]:
			pass
		elif s[startIndex] == '?' and s[endIndex] != '?':
			p = startIndex
			while p >= 0:
				s[p] = s[endIndex]
				p -= k
		elif s[startIndex] != '?' and s[endIndex] == '?':
			s[endIndex] = s[startIndex]
		elif s[startIndex] == '?' and s[endIndex] == '?':
			pass
		else:
			k_bal = False
		startIndex += 1
		endIndex += 1
	return kBalanced(s[0:k]) and k_bal

