	if n <= 2:
		cycle = n * m
		(q1, q2, q3, k) = (k // cycle, k // cycle, k // cycle, k % cycle)
		q1 += k > 0
		q3 += k >= m * (x - 1) + y
		return (q1, q2, q3)
