		a = self.a
		for x in a:
			if x % self.d != a[0] % self.d:
				self.answer = -1
				return
		a = [x // self.d for x in a]
		a.sort()
		d = [sum(a)] + [0 for _ in range(1, a[-1] + 1)]
		lessCurrentLevel = 0
		counter = Counter(a)
		for level in range(1, a[-1] + 1):
			lessCurrentLevel += counter[level - 1]
			d[level] = d[level - 1] + lessCurrentLevel - (len(a) - lessCurrentLevel)
		self.answer = min(d)

	def solve2(self):
		(a, d) = (self.a, self.d)
		for i in range(1, len(a)):
