def count_ones(n, limit_left, limit_right):

	def tree_nodes(n):
		if n == 0:
			return 1
		return 2 ** n.bit_length() - 1

	def f(n, start):
		if start > limit_right:
			return 0
		nodes = tree_nodes(n)
