def count_ones(n, limit_left, limit_right):
	subarray = [None] * (limit_right - limit_left + 1)

	def f(n, start):
		if start > limit_right:
			return
		nodes = max(1, 2 ** n.bit_length() - 1)
		if start + nodes <= limit_left:
			return
		subtree_nodes = (nodes - 1) // 2
		if subtree_nodes > 0:
			f(n // 2, start)
			f(n // 2, start + subtree_nodes + 1)
		if limit_left <= start + subtree_nodes <= limit_right:
			subarray[start - limit_left + subtree_nodes] = n % 2
	f(n, 0)
	return sum(subarray)
