	return (a >= b if mark else a > b) if flag else a <= b if mark else a < b

def build(nums, iter, flag, mark, dv):
	(h, stack) = ([dv for i in range(len(nums))], collections.deque([]))
	for i in iter:
		while stack and check(nums[stack[-1]], nums[i], flag, mark):
			h[stack.pop()] = i
		stack.append(i)
	return h

