class SegmentTree:

	def __init__(self, n):
		self.tree = [0] * (2 * n)
		self.n = n

	def query(self, l, r, val):
		l += self.n
		r += self.n
		while l < r:
			if l % 2 == 1:
				self.tree[l] = val
				l += 1
			if r % 2 == 1:
				r -= 1
				self.tree[r] = val
			l //= 2
			r //= 2

	def search(self, idx):
		idx += self.n
		res = [0, 0]
		while idx > 1:
			if self.tree[idx] and self.tree[idx][1] >= res[1]:
				res = self.tree[idx].copy()
			idx //= 2
		return res

def solve1(n, fights):
	ans = [0] * (n + 1)
	tree = SegmentTree(n)
	c = 0
	for (l, r, x) in fights[::-1]:
		tree.query(l - 1, x - 1, [x, c])
		tree.query(x, r, [x, c])
		c += 1
	for i in range(n):
		if fights[-1][2] != i + 1:
			ans[i + 1] = tree.search(i)[0]
	return ans[1:]

