from types import GeneratorType

def iterative(f, stack=[]):

	def wrapped_func(*args, **kwargs):
		if stack:
			return f(*args, **kwargs)
		to = f(*args, **kwargs)
		while True:
			if type(to) is GeneratorType:
				stack.append(to)
				to = next(to)
				continue
			stack.pop()
			if not stack:
				break
			to = stack[-1].send(to)
		return to
	return wrapped_func

@iterative
def build_segment(a, tree, i_tree, right, left):
	if right == left:
		tree[i_tree] = a[right]
	else:
		mid = (right + left) // 2
		yield build_segment(a, tree, 2 * i_tree, right, mid)
		yield build_segment(a, tree, 2 * i_tree + 1, mid + 1, left)

@iterative
def querry(a, tree, i_tree, left, right, ql, qr, x):
	if right == left and a[right] == 0:
		if not ql <= right <= qr or x == right + 1:
			yield tree[i_tree]
		else:
			a[right] = x
			tree[i_tree] = 1
			yield 1
	if qr < left or ql > right:
		yield tree[i_tree]
	if ql <= left and right <= qr:
		if tree[i_tree]:
			yield 1
		else:
			mid = (right + left) // 2
			yield querry(a, tree, 2 * i_tree, left, mid, ql, qr, x)
			yield querry(a, tree, 2 * i_tree + 1, mid + 1, right, ql, qr, x)
			tree[i_tree] = min(tree[2 * i_tree], tree[i_tree * 2 + 1])
			yield tree[i_tree]
	else:
		mid = (right + left) // 2
		yield querry(a, tree, 2 * i_tree, left, mid, ql, qr, x)
		yield querry(a, tree, 2 * i_tree + 1, mid + 1, right, ql, qr, x)
		tree[i_tree] = min(tree[2 * i_tree], tree[i_tree * 2 + 1])
		yield tree[i_tree]
