class segmenttree:

	def __init__(self, arr, n):
		(self.tree, self.n) = ([0] * (2 * n), n)
		if arr:
			for i in range(2 * n - 1, 0, -1):
				if i >= n:
					self.tree[i] = arr[i - n]
				else:
					self.tree[i] = self.tree[i << 1] + self.tree[(i << 1) + 1]

	def query(self, l, r, val):
		res = 0
		l += self.n
		r += self.n
		while l < r:
			if l & 1:
				self.tree[l] = val
				l += 1
			if r & 1:
				r -= 1
				self.tree[r] = val
			l >>= 1
			r >>= 1
		return res

	def search(self, ix):
		ix += self.n
		ret = [0, 0]
		while ix > 1:
			if self.tree[ix] and self.tree[ix][1] >= ret[1]:
				ret = self.tree[ix].copy()
			ix >>= 1
		return ret
