def get_number(a):
	dict_ = {}
	sorted_a = sorted(a)
	curr_item = sorted_a[0]
	count = 1
	for i in range(1, len(a)):
		if sorted_a[i] != curr_item:
			dict_[curr_item] = count
			count = 1
			curr_item = sorted_a[i]
		else:
			count += 1
	dict_[curr_item] = count
	sum_ = 0
	for item in dict_:
		sum_ += C(dict_[item], 2)
	return sum_

def get_repeated(a):
	dict_ = {}
	sorted_a = sorted(a)
	curr_item = sorted_a[0]
	count = 1
	for i in range(1, len(a)):
		if sorted_a[i] != curr_item:
			dict_[curr_item] = count
			count = 1
			curr_item = sorted_a[i]
		else:
			count += 1
	dict_[curr_item] = count
	sum_ = 0
	for item in dict_:
		if dict_[item] > 1:
			sum_ += C(dict_[item], 2)
	return sum_

