def block(arr, index):
	ref = arr[0][index]
	count = 0
	pairs = 0
	for (i, num) in enumerate(arr):
		if i < len(arr) - 1 and num[index] == ref:
			count += 1
		else:
			if i == len(arr) - 1 and num[index] == ref:
				count += 1
			pairs = pairs + count * (count - 1) // 2
			ref = num[index]
			count = 1
	return pairs

