def solver(L):
	xDict = dict()
	yDict = dict()
	xyDict = dict()
	for (x, y) in L:
		if (x, y) in xyDict:
			xyDict[x, y] += 1
		else:
			xyDict[x, y] = 1
	repeats = 0
	for xy in xyDict:
		n = xyDict[xy]
		repeats += n * (n - 1) // 2
	for (x, y) in L:
		if x in xDict:
			xDict[x].append(y)
		else:
			xDict[x] = [y]
		if y in yDict:
			yDict[y].append(x)
		else:
			yDict[y] = [x]
	xSames = 0
	for x in xDict:
		n = len(xDict[x])
		xSames += n * (n - 1) // 2
	ySames = 0
	for y in yDict:
		n = len(yDict[y])
		ySames += n * (n - 1) // 2
	total = xSames + ySames - repeats
	return total

