from sys import stdin, stdout

class SOLVE:

	def solve(self):
		R = stdin.readline
		W = stdout.write
		(xfreq, yfreq, xyfreq) = ({}, {}, {})
		for i in range(int(R())):
			(p, q) = [x for x in R().split()]
			s = ('' if p[0] == '-' else '+') + p + ('' if q[0] == '-' else '+') + q
			if xyfreq.get(s):
				xyfreq[s] += 1
			else:
				xyfreq[s] = 1
			if xfreq.get(p):
				xfreq[p] += 1
			else:
				xfreq[p] = 1
			if yfreq.get(q):
				yfreq[q] += 1
			else:
				yfreq[q] = 1
		pairs = 0
		for s in xfreq:
			pairs += xfreq[s] * (xfreq[s] - 1) // 2
		for s in yfreq:
			pairs += yfreq[s] * (yfreq[s] - 1) // 2
		for s in xyfreq:
			pairs -= xyfreq[s] * (xyfreq[s] - 1) // 2
		W('%d\n' % pairs)
		return 0

def main():
	s = SOLVE()
	s.solve()
