	index = [set() for _ in range(m)]
	r = []
	while events:
		ele = events.pop()
		if ele is None:
			r.clear()
		else:
			for n in r:
				index[n].add(ele)
			index[ele].update(r)
			r.append(ele)
	whole = set(range(m))
	for i in range(m):
		index[i] = whole - index[i] - {i}
	maxs = [0] * m
	whole = set()
	for i in range(m):
		whole.add(i)
		maxs[i] = max(maxs[i - 1], find_max_clique(whole & index[i], 1, maxs[i - 1], index, maxs))
	return maxs[-1]

