	i = 0
	while i < len(ok):
		if not ok[i]:
			if i + 1 != arr[i + 1] and (i + 1 >= len(ok) or not ok[i + 1]):
				return False
			i += 1
		else:
			j = i
			while j < len(ok) and ok[j]:
				j += 1
			if sum(arr[i:j + 1]) != sum(range(i, j + 1)):
				return False
			i = j
	return True

