	while i < n - 1:
		if s[i] == '0':
			r = -1
		else:
			if r == -1:
				r = n_r
				n_r += 1
			ranges[i] = r
			ranges[i + 1] = r
		i += 1
	for j in range(n):
		if indices[j] != j:
			dest = j
			target = j + 1
			t_ind = indices[j]
			if ranges[dest] == -1 or ranges[t_ind] == -1 or ranges[dest] != ranges[t_ind]:
				return False
			num_at_index = a[j]
			swap(indices, j, num_at_index - 1)
			a[j] = target
			a[indices[num_at_index - 1]] = num_at_index
	return True

