def find(par, a):
	if par[a] == a:
		return a
	par[a] = find(par, par[a])
	return par[a]

def union(par, rnk, a, b):
	a = find(par, a)
	b = find(par, b)
	if a == b:
		return
	if rnk[a] < rnk[b]:
		par[a] = b
	else:
		par[b] = a
		if rnk[a] == rnk[b]:
			rnk[a] += 1

